"""Two reproducible mechanism figures for atlases and Stokes orientation."""
from pathlib import Path
from html import escape
ROOT=Path(__file__).resolve().parents[1]/'grad-math/images'
STYLE='text{font-family:system-ui,sans-serif;fill:#24313a} .title{font-size:25px;font-weight:700}.label{font-size:19px}.small{font-size:16px}.line{fill:none;stroke:#315f9d;stroke-width:2.5}.red{fill:none;stroke:#b64335;stroke-width:3}.green{fill:none;stroke:#39734d;stroke-width:3}'
def text(x,y,t,cls='label',anchor='start'):return f'<text x="{x}" y="{y}" class="{cls}" text-anchor="{anchor}">{escape(t)}</text>'
def path(d,color='line',arrow=False):return f'<path d="{d}" class="{color}"'+(' marker-end="url(#arrow)"' if arrow else '')+'/>'
def wrap(title,parts):return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1100 650" role="img" aria-label="'+title+'"><title>'+title+'</title><defs><style>'+STYLE+'</style><marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto"><path d="M0 0 L10 5 L0 10 Z" fill="#555"/></marker></defs><rect width="1100" height="650" fill="#fff"/>'+''.join(parts)+'</svg>\n'
p=[text(40,45,'两张坐标卡描述同一点、同一切向量','title'),'<circle cx="250" cy="270" r="110" fill="#edf4f8" stroke="#315f9d" stroke-width="2.5"/>',path('M70 270 L505 270'),text(485,299,'x'),path('M250 115 L250 397'),text(228,112,'y'),path('M250 160 L470 270','line',True),path('M305 270 L338 204','red'),path('M250 380 L305 270','red',True),'<circle cx="338" cy="204" r="6" fill="#9b6a12"/>',text(347,190,'p=(0.8,0.6)','small'),text(265,151,'N=(0,1)','small'),text(265,398,'S=(0,−1)','small'),text(446,321,'u=2'),text(324,299,'v=1/2'),path('M338 204 L302 156','green',True),text(56,429,'蓝：从 N 投到 y=0，u=x/(1−y)','small'),text(56,456,'红：从 S 投到 y=0，v=x/(1+y)','small'),text(570,125,'同一点的两份坐标'),text(590,175,'u=2   →   v=1/u=1/2'),text(570,244,'同一切向量的两份分量'),text(590,289,'w_N=1   →   w_S=(−1/u²)w_N=−1/4'),text(570,352,'转移 Jacobian 非零，秩为 1。','small'),text(570,382,'分量改变；方向导数这个操作不变。','small'),text(570,442,'重叠区排除两极：u≠0。','small'),text(56,530,'为什么不能只用一张卡？','label'),text(56,563,'S¹ 紧致，实数轴的非空开集不紧致；它们不可能同胚。','small'),text(56,602,'“每点附近有坐标”与“全空间有一张坐标卡”是不同的要求。','small')]
(ROOT/'mfld-01-chart.svg').write_text(wrap('立体投影的坐标与切向量换算',p))
p=[text(40,45,'Stokes 的机制：内部边界两两抵消','title'),text(60,92,'把正向方形拆成两片'),'<rect x="70" y="130" width="340" height="250" fill="#edf4f8" stroke="#aaa"/>',path('M70 380 L240 380 L240 130 L70 130 L70 380','red'),path('M240 380 L410 380 L410 130 L240 130 L240 380','line'),path('M70 380 L165 380','red',True),path('M410 380 L410 235','line',True),path('M410 130 L315 130','line',True),path('M70 130 L70 275','red',True),path('M233 310 L233 200','red',True),path('M247 200 L247 310','line',True),text(90,418,'共同边：一片向上、另一片向下。','small'),text(90,448,'两条积分相加为零，只剩外边界。','small'),text(535,92,'环域也可以用 Stokes'),'<circle cx="775" cy="255" r="125" fill="#edf4f8" stroke="#315f9d" stroke-width="2"/>','<circle cx="775" cy="255" r="62" fill="#fff" stroke="#b64335" stroke-width="2"/>',path('M900 255 A125 125 0 0 0 775 130','line',True),path('M775 193 A62 62 0 0 1 837 255','red',True),text(775,260,'孔','label','middle'),text(535,418,'外圈逆时针 +2π；内圈顺时针 −2π。','small'),text(535,448,'角度形式 α 在环域光滑，dα=0。','small'),text(60,517,'∫∂M α = 2π − 2π = 0 = ∫M dα','label'),text(60,557,'遗漏内边界会得到假矛盾；把整个圆盘填满则会碰到原点奇点。','small'),text(60,600,'反转区域定向，所有诱导边界同时反转，等式两边一起变号。','small')]
(ROOT/'mfld-02-stokes.svg').write_text(wrap('分片边界抵消与环域诱导定向',p))
print('Wrote 2 manifold/forms mechanism figures')
